package apis

import (
	"net/http"

	"github.com/lumm2509/pocketbomb/core"
	"github.com/lumm2509/pocketbomb/tools/router"
	"github.com/lumm2509/pocketbomb/tools/types"
	validation "github.com/pocketbase/ozzo-validation/v4"
)

// bindOAuth2ClientAPIKeysApi registers the OAuth2 clients API keys management endpoints
// (oauth2_clients read = list, oauth2_clients write = create/update/rotate/delete).
//
// The keys are created and changed only through these endpoints (the records API create/update
// of the _apiKeys collection is Owner only) because the tokens are generated by the server
// and the private ones are returned only once.
//
// The key permissions are only a ceiling of the requests carrying the key (they never grant
// anything on their own, see [core.Authorize]) and therefore they don't have to be covered
// by the actor permissions. The model invariants are enforced by the _apiKeys model hooks.
func bindOAuth2ClientAPIKeysApi(r *router.RouterGroup[*core.RequestEvent]) {
	read := RequirePermission(core.PermissionResourceOAuth2Clients, core.PermissionLevelRead)
	write := RequirePermission(core.PermissionResourceOAuth2Clients, core.PermissionLevelWrite)

	sub := r.Group("/clients/{id}/api-keys")
	sub.GET("", oauth2ClientAPIKeysList).Bind(read)
	sub.POST("", oauth2ClientAPIKeyCreate).Bind(write)
	sub.PATCH("/{keyId}", oauth2ClientAPIKeyUpdate).Bind(write)
	sub.POST("/{keyId}/rotate-secret", oauth2ClientAPIKeyRotate).Bind(write)
	sub.DELETE("/{keyId}", oauth2ClientAPIKeyDelete).Bind(write)
}

type apiKeyResponse struct {
	Id             string           `json:"id"`
	Name           string           `json:"name"`
	ClientRef      string           `json:"clientRef"`
	Kind           string           `json:"kind"`
	BuyerContext   string           `json:"buyerContext"`
	TokenPrefix    string           `json:"tokenPrefix"`
	Token          string           `json:"token"` // the public keys only
	Permissions    core.Permissions `json:"permissions"`
	AllowedOrigins []string         `json:"allowedOrigins"`
	Disabled       bool             `json:"disabled"`
	Expired        bool             `json:"expired"`
	ExpiresAt      types.DateTime   `json:"expiresAt"`
	LastUsedAt     types.DateTime   `json:"lastUsedAt"`
	CreatedBy      string           `json:"createdBy"`
	Created        types.DateTime   `json:"created"`
	Updated        types.DateTime   `json:"updated"`
}

func newAPIKeyResponse(key *core.APIKey) *apiKeyResponse {
	origins := key.AllowedOrigins()
	if origins == nil {
		origins = []string{}
	}

	return &apiKeyResponse{
		Id:             key.Id,
		Name:           key.Name(),
		ClientRef:      key.ClientRef(),
		Kind:           key.Kind(),
		BuyerContext:   key.BuyerContext(),
		TokenPrefix:    key.TokenPrefix(),
		Token:          key.Token(),
		Permissions:    key.Permissions(),
		AllowedOrigins: origins,
		Disabled:       key.Disabled(),
		Expired:        key.IsExpired(),
		ExpiresAt:      key.ExpiresAt(),
		LastUsedAt:     key.LastUsedAt(),
		CreatedBy:      key.CreatedBy(),
		Created:        key.Created(),
		Updated:        key.Updated(),
	}
}

// apiKeyTokenResponse is the create and rotate response
// (the plain token is returned only once; the public token is also always part of the key).
type apiKeyTokenResponse struct {
	APIKey *apiKeyResponse `json:"apiKey"`
	Token  string          `json:"token"`
}

// findManagedAPIKeyClient returns the path OAuth2 client and checks whether
// the actor could manage its keys (the same rules as for the client secret).
func findManagedAPIKeyClient(e *core.RequestEvent, checkChange bool) (*core.OAuth2Client, error) {
	client, err := e.App.FindOAuth2ClientById(e.Request.PathValue("id"))
	if err != nil {
		return nil, e.NotFoundError("Missing or invalid OAuth2 client.", err)
	}

	// the keys of the _superusers issuer and of the first-party clients are Owner only
	// (similar to the client secret, the keys are client credentials)
	if checkChange {
		if err := core.CheckOAuth2ClientChange(e.App, e.ActorInfo(), client.Record); err != nil {
			return nil, e.ForbiddenError("Only the Owners could manage the API keys of the _superusers and of the first-party OAuth2 clients.", err)
		}
	}

	return client, nil
}

// findClientAPIKey returns the path API key of the provided client.
func findClientAPIKey(e *core.RequestEvent, client *core.OAuth2Client) (*core.APIKey, error) {
	key, err := e.App.FindAPIKeyById(e.Request.PathValue("keyId"))
	if err != nil || key.ClientRef() != client.Id {
		return nil, e.NotFoundError("Missing or invalid API key.", err)
	}

	return key, nil
}

// GET /api/oauth2/clients/{id}/api-keys
//
// Returns the client API keys (newest first; never the private tokens).
func oauth2ClientAPIKeysList(e *core.RequestEvent) error {
	client, err := findManagedAPIKeyClient(e, false)
	if err != nil {
		return err
	}

	keys, err := e.App.FindAllAPIKeysByClient(client.Id)
	if err != nil {
		return e.InternalServerError("Failed to load the API keys.", err)
	}

	result := make([]*apiKeyResponse, len(keys))
	for i, key := range keys {
		result[i] = newAPIKeyResponse(key)
	}

	return e.JSON(http.StatusOK, result)
}

type apiKeyCreateForm struct {
	Name           string           `form:"name" json:"name"`
	Kind           string           `form:"kind" json:"kind"`
	BuyerContext   string           `form:"buyerContext" json:"buyerContext"`
	AllowedOrigins []string         `form:"allowedOrigins" json:"allowedOrigins"`
	Permissions    core.Permissions `form:"permissions" json:"permissions"`
	ExpiresAt      types.DateTime   `form:"expiresAt" json:"expiresAt"`
}

func (form *apiKeyCreateForm) validate() error {
	return validation.ValidateStruct(form,
		validation.Field(&form.Kind, validation.Required, validation.In(core.APIKeyKindPublic, core.APIKeyKindPrivate)),
	)
}

// POST /api/oauth2/clients/{id}/api-keys
//
// Creates a new API key for the specified client and returns it with its plain token
// (the private tokens are not retrievable later).
func oauth2ClientAPIKeyCreate(e *core.RequestEvent) error {
	client, err := findManagedAPIKeyClient(e, true)
	if err != nil {
		return err
	}

	form := &apiKeyCreateForm{}
	if err := e.BindBody(form); err != nil {
		return e.BadRequestError("An error occurred while loading the submitted data.", err)
	}
	if err := form.validate(); err != nil {
		return e.BadRequestError("An error occurred while validating the submitted data.", err)
	}

	key := core.NewAPIKey(e.App)
	key.SetName(form.Name)
	key.SetClientRef(client.Id)
	key.SetKind(form.Kind)
	key.SetBuyerContext(form.BuyerContext)
	key.SetAllowedOrigins(form.AllowedOrigins)
	key.SetPermissions(form.Permissions)
	key.SetExpiresAt(form.ExpiresAt)
	if e.Auth != nil {
		key.SetCreatedBy(e.Auth.Id)
	}
	token := key.GenerateToken()

	if err := e.App.Save(key); err != nil {
		return firstApiError(err, e.BadRequestError("Failed to create the API key.", err))
	}

	setOAuth2NoStoreHeaders(e)

	return e.JSON(http.StatusOK, apiKeyTokenResponse{APIKey: newAPIKeyResponse(key), Token: token})
}

type apiKeyUpdateForm struct {
	Name           *string           `form:"name" json:"name"`
	Disabled       *bool             `form:"disabled" json:"disabled"`
	AllowedOrigins *[]string         `form:"allowedOrigins" json:"allowedOrigins"`
	Permissions    *core.Permissions `form:"permissions" json:"permissions"`
	ExpiresAt      *types.DateTime   `form:"expiresAt" json:"expiresAt"`
}

// PATCH /api/oauth2/clients/{id}/api-keys/{keyId}
//
// Updates the specified API key name, state (disabled), allowed origins,
// permissions or expiration date (the client and the kind are immutable).
func oauth2ClientAPIKeyUpdate(e *core.RequestEvent) error {
	client, err := findManagedAPIKeyClient(e, true)
	if err != nil {
		return err
	}

	key, err := findClientAPIKey(e, client)
	if err != nil {
		return err
	}

	form := &apiKeyUpdateForm{}
	if err := e.BindBody(form); err != nil {
		return e.BadRequestError("An error occurred while loading the submitted data.", err)
	}

	if form.Name != nil {
		key.SetName(*form.Name)
	}
	if form.Disabled != nil {
		key.SetDisabled(*form.Disabled)
	}
	if form.AllowedOrigins != nil {
		key.SetAllowedOrigins(*form.AllowedOrigins)
	}
	if form.Permissions != nil {
		key.SetPermissions(*form.Permissions)
	}
	if form.ExpiresAt != nil {
		key.SetExpiresAt(*form.ExpiresAt)
	}

	if err := e.App.Save(key); err != nil {
		return firstApiError(err, e.BadRequestError("Failed to update the API key.", err))
	}

	return e.JSON(http.StatusOK, newAPIKeyResponse(key))
}

// POST /api/oauth2/clients/{id}/api-keys/{keyId}/rotate-secret
//
// Replaces the specified API key token with a new one (the old token stops working immediately)
// and returns the key with its new plain token.
func oauth2ClientAPIKeyRotate(e *core.RequestEvent) error {
	client, err := findManagedAPIKeyClient(e, true)
	if err != nil {
		return err
	}

	key, err := findClientAPIKey(e, client)
	if err != nil {
		return err
	}

	token := key.GenerateToken()

	if err := e.App.Save(key); err != nil {
		return firstApiError(err, e.BadRequestError("Failed to rotate the API key.", err))
	}

	setOAuth2NoStoreHeaders(e)

	return e.JSON(http.StatusOK, apiKeyTokenResponse{APIKey: newAPIKeyResponse(key), Token: token})
}

// DELETE /api/oauth2/clients/{id}/api-keys/{keyId}
func oauth2ClientAPIKeyDelete(e *core.RequestEvent) error {
	client, err := findManagedAPIKeyClient(e, true)
	if err != nil {
		return err
	}

	key, err := findClientAPIKey(e, client)
	if err != nil {
		return err
	}

	if err := e.App.Delete(key); err != nil {
		return firstApiError(err, e.BadRequestError("Failed to delete the API key.", err))
	}

	return e.NoContent(http.StatusNoContent)
}
